// Embeds py/tracer.py into js/pytracer.js (run: node build.js)
const fs = require('fs');
const py = fs.readFileSync(__dirname + '/py/tracer.py', 'utf8');
fs.writeFileSync(__dirname + '/js/pytracer.js',
  '/* AUTO-GENERATED by build.js from py/tracer.py — do not edit by hand */\n' +
  'globalThis.CL = globalThis.CL || {};\nCL.PY_TRACER_SRC = ' + JSON.stringify(py) + ';\n');
console.log('pytracer.js written', py.length, 'chars');
